message.content:
这是根据您提供的第6页任务生成的可直接运行的HTML文档，用于展示“资料边界与状态说明”页面。它围绕已完成、计划、未确定三类状态划分信息，呈现试件18件、工况6类、测点24个等计划内容，并标注事实来源，适合研究开题评审场景预览。
```html
<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8"/>
<style>
  html,body{margin:0;padding:0;width:1920px;height:1080px;overflow:hidden;background:#F5F2E9;}
  *{box-sizing:border-box;}
  :root{
    --theme-bg:#F5F2E9;
    --theme-surface:#F3F0E7;
    --theme-ink:#1B2620;
    --theme-muted:#5C665D;
    --theme-accent-primary:#4F5E43;
    --theme-accent-secondary:#B4914A;
    --theme-accent-tertiary:#8C9FB2;
    --theme-line:#A3AC9E;
    --font-display:"Songti SC","Noto Serif SC","Source Han Serif SC",SimSun,Georgia,serif;
    --font-body:"PingFang SC","Hiragino Sans GB","Microsoft YaHei","Helvetica Neue",Arial,sans-serif;
  }
  .slide{
    position:relative;width:1920px;height:1080px;overflow:hidden;
    background:var(--theme-bg);color:var(--theme-ink);
    font-family:var(--font-body);
  }
  /* ---------- paper field ---------- */
  .bg-field{position:absolute;inset:0;z-index:0;
    background:
      radial-gradient(1100px 780px at 2% 0%,rgba(180,145,74,.09),transparent 70%),
      radial-gradient(880px 760px at 47% 46%,rgba(140,159,178,.10),transparent 70%),
      radial-gradient(950px 760px at 95% 95%,rgba(79,94,67,.10),transparent 72%),
      linear-gradient(168deg,#F8F5EC 0%,#F5F2E9 52%,#EFECE1 100%);
  }
  .bg-field:after{content:"";position:absolute;inset:0;
    background:repeating-linear-gradient(90deg,rgba(27,38,32,.045) 0 1px,transparent 1px 160px);
    opacity:.85;
  }
  .dot-field{position:absolute;z-index:1;opacity:.34;
    background-image:radial-gradient(circle,rgba(27,38,32,.45) 1.05px,transparent 1.15px);
    background-size:15px 15px;
  }
  .dot-top{left:1180px;top:0;width:520px;height:140px;}
  .dot-bottom{left:820px;top:912px;width:900px;height:168px;opacity:.20;}
  .gridline{position:absolute;z-index:1;background:rgba(27,38,32,.055);}
  .gl1{left:480px;top:0;width:1px;height:1080px;}
  .gl2{left:960px;top:0;width:1px;height:1080px;}
  .gl3{left:1440px;top:0;width:1px;height:1080px;}

  /* ---------- rules & chrome ---------- */
  .top-rule{position:absolute;left:96px;top:48px;width:1760px;height:1px;z-index:6;background:rgba(27,38,32,.34);}
  .left-rule{position:absolute;left:60px;top:40px;width:1px;height:1000px;z-index:6;background:rgba(27,38,32,.26);}
  .rail-tick{position:absolute;left:54px;width:13px;height:1px;z-index:7;background:rgba(27,38,32,.42);}
  .rail-tick.t1{top:150px;}
  .rail-tick.t2{top:600px;}
  .rail-tick.t3{top:900px;}
  .rail-label{position:absolute;left:42px;top:840px;z-index:15;
    transform:rotate(-90deg);transform-origin:left top;
    font-size:13px;font-weight:600;letter-spacing:5px;color:#637067;white-space:nowrap;
  }
  .page-no{position:absolute;left:28px;top:61px;z-index:15;
    font-size:14px;font-weight:600;letter-spacing:2px;color:#657066;
  }
  .top-meta{position:absolute;left:98px;top:61px;z-index:15;
    font-size:15px;font-weight:600;letter-spacing:4px;color:#4f5b53;
  }
  .register{position:absolute;right:-72px;top:-72px;width:286px;height:286px;z-index:3;
    border-radius:50%;border:1px solid rgba(27,38,32,.30);
  }
  .register .r2{position:absolute;inset:12px;border-radius:50%;border:1px solid rgba(27,38,32,.18);}
  .register .r3{position:absolute;inset:28px;border-radius:50%;
    background:conic-gradient(from 210deg,rgba(79,94,67,.18),rgba(79,94,67,0) 26%,rgba(140,159,178,.28) 52%,rgba(140,159,178,.07) 78%,rgba(79,94,67,.18));
  }
  .register .r4{position:absolute;inset:40px;border-radius:50%;
    background:rgba(245,242,233,.9);border:1px solid rgba(27,38,32,.08);
  }
  .register .r5{position:absolute;inset:58px;border-radius:50%;
    background:rgba(140,159,178,.24);border:1px solid rgba(27,38,32,.09);
  }
  .register .dot{position:absolute;left:56px;top:180px;width:13px;height:13px;border-radius:50%;
    background:var(--theme-accent-secondary);box-shadow:0 0 0 5px rgba(180,145,74,.13);
  }
  .edge-prism{position:absolute;z-index:2;left:1866px;top:330px;width:300px;height:900px;
    transform:rotate(15deg);transform-origin:top left;opacity:.9;
    background:linear-gradient(180deg,rgba(140,159,178,.20),rgba(140,159,178,.06) 70%,rgba(140,159,178,0));
  }
  .edge-prism:after{content:"";position:absolute;left:88px;top:0;width:60px;height:900px;background:rgba(255,255,255,.34);}

  /* ---------- header ---------- */
  .head{position:absolute;left:96px;top:126px;z-index:10;width:1400px;}
  .eyebrow{display:flex;align-items:center;gap:16px;
    font-size:15px;font-weight:700;letter-spacing:4.6px;color:var(--theme-accent-primary);
  }
  .eyebrow .tick{display:inline-block;width:34px;height:2px;background:var(--theme-accent-secondary);}
  h1{margin:22px 0 0 0;font-family:var(--font-display);font-weight:700;
    font-size:92px;line-height:1.06;letter-spacing:2px;color:#1B2620;
  }
  .sub{margin:22px 0 0 0;font-size:21px;line-height:1.6;color:var(--theme-muted);letter-spacing:1px;max-width:1180px;}

  /* ---------- cards ---------- */
  .cards{position:absolute;left:96px;top:424px;width:1728px;height:486px;z-index:10;
    display:grid;grid-template-columns:554px 554px 554px;gap:33px;
  }
  .card{position:relative;height:486px;padding:34px 36px 30px 36px;
    background:linear-gradient(162deg,rgba(255,255,255,.62) 0%,rgba(243,240,231,.46) 100%);
    border:1px solid rgba(27,38,32,.16);
    box-shadow:0 12px 34px rgba(27,38,32,.055);
    display:flex;flex-direction:column;
  }
  .card .bar{position:absolute;left:-1px;top:-1px;height:3px;width:calc(100% + 2px);}
  .c1 .bar{background:var(--theme-accent-tertiary);}
  .c2 .bar{background:var(--theme-accent-primary);}
  .c3 .bar{background:var(--theme-accent-secondary);}

  .card-head{display:flex;justify-content:space-between;align-items:baseline;
    font-size:13px;font-weight:700;letter-spacing:3.4px;color:#7A8379;
  }
  .card-head .idx{font-family:var(--font-display);font-size:20px;letter-spacing:1px;color:#9A8358;}
  .c1 .card-head .idx{color:#6F8395;}
  .c2 .card-head .idx{color:var(--theme-accent-primary);}

  .card h2{margin:14px 0 0 0;font-family:var(--font-display);font-weight:700;
    font-size:42px;line-height:1.2;letter-spacing:3px;color:#1B2620;
  }
  .card .divider{margin:18px 0 0 0;height:1px;background:rgba(27,38,32,.20);}
  .card-body{margin-top:20px;flex:1;display:flex;flex-direction:column;}

  /* card 1 */
  .big-none{font-family:var(--font-display);font-size:112px;line-height:1;font-weight:700;
    color:#54626F;letter-spacing:4px;
  }
  .c1 .note{margin:20px 0 0 0;font-size:19px;line-height:1.72;color:#3D473F;letter-spacing:.6px;max-width:420px;}
  .c1 .fill{margin-top:auto;display:flex;align-items:center;gap:12px;
    font-size:14px;letter-spacing:2.4px;color:#8B7A52;
  }
  .c1 .fill i{display:block;width:26px;height:1px;background:rgba(180,145,74,.85);font-style:normal;}

  /* card 2 */
  .metric-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px 18px;}
  .metric .num{font-family:var(--font-display);font-size:46px;line-height:1;font-weight:700;color:#1B2620;}
  .metric .unit{font-family:var(--font-body);font-size:17px;font-weight:600;color:#5C665D;margin-left:6px;letter-spacing:.5px;}
  .metric .cap{margin-top:9px;font-size:14px;letter-spacing:1.8px;color:#6B746A;}
  .phase{margin-top:22px;padding-top:16px;border-top:1px dashed rgba(27,38,32,.28);}
  .phase-row{display:flex;gap:12px;font-size:15px;line-height:1.95;letter-spacing:.4px;}
  .phase-row .pm{min-width:92px;font-weight:700;color:var(--theme-accent-primary);}
  .phase-row .pd{color:#2A342D;}

  /* card 3 */
  .c3 .lead{margin:0 0 14px 0;font-size:17px;line-height:1.7;color:#4A544B;letter-spacing:.5px;}
  .c3 ul{list-style:none;margin:0;padding:0;}
  .c3 li{display:flex;align-items:center;gap:14px;padding:16px 0;
    border-bottom:1px dashed rgba(27,38,32,.24);font-size:20px;letter-spacing:.8px;color:#1B2620;
  }
  .c3 li:first-child{border-top:1px dashed rgba(27,38,32,.24);}
  .c3 li .mk{width:8px;height:8px;background:var(--theme-accent-secondary);flex:none;transform:rotate(45deg);}
  .c3 li .lbl{margin-left:auto;font-size:13px;letter-spacing:2.2px;color:#8B7A52;font-weight:600;}
  .c3 .tail{margin-top:auto;font-size:14px;line-height:1.7;color:#6B746A;letter-spacing:.6px;}

  /* ---------- footer ---------- */
  .foot-line{position:absolute;left:96px;top:948px;width:1728px;height:1px;z-index:10;background:rgba(27,38,32,.24);}
  .foot-src{position:absolute;left:96px;top:972px;z-index:10;
    font-size:15px;letter-spacing:1.4px;color:#5C665D;
  }
  .foot-src b{font-weight:700;color:#3A453C;}
  .foot-page{position:absolute;right:96px;bottom:44px;z-index:10;
    font-family:var(--font-display);font-size:17px;font-weight:700;letter-spacing:3px;color:#3A453C;
  }
</style>
</head>
<body>
<main class="slide">
  <div class="bg-field"></div>
  <div class="dot-field dot-top"></div>
  <div class="dot-field dot-bottom"></div>
  <div class="gridline gl1"></div>
  <div class="gridline gl2"></div>
  <div class="gridline gl3"></div>
  <div class="edge-prism"></div>

  <div class="register">
    <div class="r2"></div>
    <div class="r3"></div>
    <div class="r4"></div>
    <div class="r5"></div>
    <div class="dot"></div>
  </div>

  <div class="top-rule"></div>
  <div class="left-rule"></div>
  <div class="rail-tick t1"></div>
  <div class="rail-tick t2"></div>
  <div class="rail-tick t3"></div>
  <div class="rail-label">资料边界与状态说明</div>
  <div class="page-no">06</div>
  <div class="top-meta">虚构隔振支架研究开题 / 研究开题评审</div>

  <header class="head">
    <div class="eyebrow"><span class="tick"></span>状态说明 · 边界界定</div>
    <h1>资料边界与状态说明</h1>
    <p class="sub">逐项区分已完成、计划与未确定三类状态，避免越过资料边界形成结论。</p>
  </header>

  <section class="cards">
    <article class="card c1">
      <div class="bar"></div>
      <div class="card-head"><span>已完成</span><span class="idx">01</span></div>
      <h2>无</h2>
      <div class="divider"></div>
      <div class="card-body">
        <div class="big-none">无</div>
        <p class="note">资料不提供已完成的实验结论，本页不作任何结果性陈述。</p>
        <div class="fill"><i></i><span>本项无已完成内容</span></div>
      </div>
    </article>

    <article class="card c2">
      <div class="bar"></div>
      <div class="card-head"><span>计划</span><span class="idx">02</span></div>
      <h2>拟设规模与周期</h2>
      <div class="divider"></div>
      <div class="card-body">
        <div class="metric-grid">
          <div class="metric"><div class="num">18<span class="unit">件</span></div><div class="cap">拟设试件</div></div>
          <div class="metric"><div class="num">6<span class="unit">类</span></div><div class="cap">设计工况</div></div>
          <div class="metric"><div class="num">24<span class="unit">个</span></div><div class="cap">拟设测点</div></div>
          <div class="metric"><div class="num">8<span class="unit">个月</span></div><div class="cap">计划周期</div></div>
        </div>
        <div class="phase">
          <div class="phase-row"><span class="pm">第 1–2 月</span><span class="pd">完成设计</span></div>
          <div class="phase-row"><span class="pm">第 3–5 月</span><span class="pd">试验准备与数据采集</span></div>
          <div class="phase-row"><span class="pm">第 6–8 月</span><span class="pd">对比分析与写作</span></div>
        </div>
      </div>
    </article>

    <article class="card c3">
      <div class="bar"></div>
      <div class="card-head"><span>未确定</span><span class="idx">03</span></div>
      <h2>待补充事项</h2>
      <div class="divider"></div>
      <div class="card-body">
        <p class="lead">以下事项资料未给出，本页不作推定：</p>
        <ul>
          <li><span class="mk"></span><span>具体性能指标</span><span class="lbl">待补充</span></li>
          <li><span class="mk"></span><span>评价口径</span><span class="lbl">待补充</span></li>
          <li><span class="mk"></span><span>最终结论</span><span class="lbl">待补充</span></li>
        </ul>
        <div class="tail">上述事项以资料后续补充为准，本开题不预设技术领先或性能提升。</div>
      </div>
    </article>
  </section>

  <div class="foot-line"></div>
  <div class="foot-src">事实来源：<b>academic.pdf</b>（虚构测评材料），未联网补充外部事实</div>
  <div class="foot-page">6 / 6</div>
</main>
</body>
</html>
```
